import java.util.*;
import java.io.*;

public class Main {
    static final int MODULUS_CONST = 1000000007;

    static class HashGen {
        private static long seed;
        static {
            seed = splitmix64(System.nanoTime() + getRandomPtr());
        }

        static long getRandomPtr() {
            long p = new Random().nextLong();
            return p;
        }

        static long splitmix64(long x) {
            x += 0x9e3779b97f4a7c15L;
            x = (x ^ (x >>> 30)) * 0xbf58476d1ce4e5b9L;
            x = (x ^ (x >>> 27)) * 0x94d049bb133111ebL;
            return x ^ (x >>> 31);
        }

        public long operator(long x) {
            return splitmix64(x ^ seed);
        }
    }

    static class ModType {
        int v;

        public ModType(long val_in) {
            val_in %= MODULUS_CONST;
            if (val_in < 0) val_in += MODULUS_CONST;
            v = (int) val_in;
        }

        public static int extended_gcd(int a, int m, int[] xy) {
            if (m == 0) {
                xy[0] = 1; xy[1] = 0;
                return a;
            }
            int[] yx = new int[2];
            int g = extended_gcd(m, a % m, yx);
            int y = yx[0], x = yx[1];
            xy[0] = yx[0];
            xy[1] = y - (a / m) * x;
            return g;
        }

        public static int inverse(int a) {
            int[] xy = new int[2];
            extended_gcd(a, MODULUS_CONST, xy);
            int x = xy[0];
            return (x % MODULUS_CONST + MODULUS_CONST) % MODULUS_CONST;
        }

        public static ModType operatorAdd(ModType a, ModType b) {
            int res = a.v + b.v;
            if (res >= MODULUS_CONST) res -= MODULUS_CONST;
            return new ModType(res);
        }

        public static ModType operatorSubtract(ModType a, ModType b) {
            int res = a.v - b.v;
            if (res < 0) res += MODULUS_CONST;
            return new ModType(res);
        }

        public static ModType operatorMultiply(ModType a, ModType b) {
            long res = ((long) a.v * b.v) % MODULUS_CONST;
            return new ModType(res);
        }

        public static ModType operatorDivide(ModType a, ModType b) {
            return a.operatorMultiply(new ModType(inverse(b.v)));
        }

        public ModType pow(long p) {
            if (p < 0) throw new IllegalArgumentException("Negative exponent");
            ModType res = new ModType(1);
            ModType base = new ModType(this.v);
            while (p > 0) {
                if ((p & 1) == 1) res = operatorMultiply(res, base);
                base = operatorMultiply(base, base);
                p >>= 1;
            }
            return res;
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st;

        int N = Integer.parseInt(br.readLine());
        ModType[][] prob = new ModType[N][N];
        for (int i = 0; i < N; i++) {
            st = new StringTokenizer(br.readLine());
            for (int j = 0; j < N; j++) {
                int p = Integer.parseInt(st.nextToken());
                prob[i][j] = new ModType(p).operatorDivide(new ModType(100));
            }
        }

        List<List<Integer>> count_mask = new ArrayList<>();
        for (int c = 0; c <= N; c++) {
            count_mask.add(new ArrayList<>());
        }
        int[] index_map = new int[1 << N];
        Arrays.fill(index_map, -1);
        for (int msk = 0; msk < (1 << N); msk++) {
            int c = Integer.bitCount(msk);
            index_map[msk] = count_mask.get(c).size();
            count_mask.get(c).add(msk);
        }

        Map<Long, ModType> state_map = new HashMap<>();
        long initial_mask = 1L << index_map[0];
        state_map.put(initial_mask, new ModType(1));

        for (int left_idx = 0; left_idx < N; left_idx++) {
            Map<Long, ModType> new_state_map = new HashMap<>();
            ModType[] prod_mask = new ModType[1 << N];
            for (int mask = 0; mask < (1 << N); mask++) {
                prod_mask[mask] = new ModType(1);
            }
            for (int mask = 0; mask < (1 << N); mask++) {
                for (int col = 0; col < N; col++) {
                    if (((mask & (1 << col)) != 0))
                        prod_mask[mask] = operatorMultiply(prod_mask[mask], prob[left_idx][col]);
                    else
                        prod_mask[mask] = operatorMultiply(prod_mask[mask], new ModType(1).operatorSubtract(prob[left_idx][col]));
                }
            }

            long[] new_bits = new long[N];
            ModType[] new_possible = new ModType[1 << N];
            Arrays.fill(new_possible, new ModType(0));

            for (Map.Entry<Long, ModType> entry : state_map.entrySet()) {
                long mask_state = entry.getKey();
                ModType prob_state = entry.getValue();
                Arrays.fill(new_bits, 0);
                for (int m : count_mask.get(left_idx)) {
                    if (((mask_state >> index_map[m]) & 1) != 0) {
                        for (int i = 0; i < N; i++) {
                            if (((m >> i) & 1) == 0) {
                                long new_mask = new_bits[i] | (1L << index_map[m | (1 << i)]);
                                new_bits[i] = new_mask;
                            }
                        }
                    }
                }
                Arrays.fill(new_possible, new ModType(0));
                for (int current_mask = 1; current_mask < (1 << N); current_mask++) {
                    int ctz = Integer.numberOfTrailingZeros(current_mask);
                    new_possible[current_mask] = operatorAdd(new_possible[current_mask & (current_mask - 1)],
                            new ModType(new_bits[ctz]));
                    long combined_mask = new_possible[current_mask].v;
                    long combined_mask_value = new_bits[ctz];
                    long combined_mask_long = combined_mask;
                    ModType val = operatorMultiply(prob_state, prod_mask[current_mask]);
                    new_state_map.put(combined_mask_long, new_state_map.getOrDefault(combined_mask_long, new ModType(0)).operatorAdd(val));
                }
            }
            state_map = new_state_map;
        }

        ModType total_prob = new ModType(0);
        for (Map.Entry<Long, ModType> entry : state_map.entrySet()) {
            long key = entry.getKey();
            if (((key >> index_map[(1 << N) - 1]) & 1) != 0) {
                total_prob = operatorAdd(total_prob, entry.getValue());
            }
        }
        System.out.println(total_prob.v);
    }

    static ModType operatorAdd(ModType a, ModType b) {
        return ModType.operatorAdd(a, b);
    }

    static ModType operatorSubtract(ModType a, ModType b) {
        return ModType.operatorSubtract(a, b);
    }

    static ModType operatorMultiply(ModType a, ModType b) {
        return ModType.operatorMultiply(a, b);
    }
}
